import { Component } from 'react'
import { connect } from 'react-redux'
import { OtpInputWrapper } from './index.style'
import { OtpInput, CustomText, Button, Container, PublicFooter } from '../../../components'
import AuthActions from '../../../redux/auth/action'
import ErrorActions from '../../../redux/error/action'
import LoadingActions from '../../../redux/loading/action'
import Cookies from 'universal-cookie'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { GlobalContext } from '../../../contextProvider/GlobalContext'
import { updateGlobalState } from '../../../state/globalState/actions'
import { getFromLocalStorageData, setToLocalStorage } from '../../../helpers/localstorage'
import { REGISTRATION_DATA } from '../../../constants/cookies'
import { AgentColorPallette } from '../../../configs/colorPallete'
import OjkFooter from '../../../components/OjkFooter'

const cookies = new Cookies()

const { loginAgent, registerAgent, sendOtp, validateAgent, resetAuthStore, verifyOtp } = AuthActions
const { resetErrorRedux } = ErrorActions
const { resetLoadingRedux } = LoadingActions

class OtpVerify extends Component {
  constructor (props) {
    super(props)
    this.state = {
      time: {},
      seconds: 60,
      error: false,
      errorMessage: ''
    }
    this.timer = 0
    this.isVNAgent = window.location.origin.includes('mitra-vn') || (process.env.REACT_APP_CC === 'VN')
    this.registrationData = getFromLocalStorageData(REGISTRATION_DATA) || {}
    this.operationId = this.registrationData?.operation_id // getValueFromLocationState.call(this, '')
  }

  componentDidMount () {
    if (!this.operationId) {
      this.props.history.goBack()
    }
    // validate the agent if loggedIn then redirect to dashboard
    this.validateIsLoggedInAgent()
    this.startCountDown()
    this.props.resetErrorRedux(['SEND_OTP', 'REGISTRATION', 'LOGIN'])
    this.props.resetLoadingRedux(['SEND_OTP', 'REGISTRATION', 'LOGIN'])
  }

  componentWillReceiveProps (nextProps) {
    // send otp prop handling
    const [, dispatchGlobal] = this.context
    const { validateAgentMessage, validateAgentStatus, resetAuthStore } = nextProps
    if (nextProps.sendOtpError && nextProps.sendOtpLoading === false) {
      NotificationManager.error(nextProps.sendOtpStatus)
      this.props.resetErrorRedux(['SEND_OTP'])
      this.props.resetLoadingRedux(['SEND_OTP'])
    } else if (!nextProps.sendOtpError && nextProps.sendOtpStatus?.operation_id && (this.operationId !== nextProps.sendOtpStatus?.operation_id)) {
      this.operationId = nextProps.sendOtpStatus?.operation_id
      setToLocalStorage(REGISTRATION_DATA, {
        ...this.registrationData,
        operation_id: this.operationId
      })
    }
    if (validateAgentMessage === 'success' && (this.operationId !== validateAgentStatus?.operation_id)) {
      this.registrationData = {
        ...this.registrationData,
        ...validateAgentStatus
      }
      this.operationId = this.registrationData.operation_id
      this.timer = 0
      this.setState({ seconds: 60 }, () => this.startCountDown())
      setToLocalStorage(REGISTRATION_DATA, {
        ...this.registrationData
      })
      resetAuthStore(['validateAgentMessage'])
    }
    if (nextProps.sendOtpError === false && nextProps.sendOtpLoading === false) {
      this.timer = 0
      this.setState({ seconds: 60 }, () => this.startCountDown())
      this.props.resetErrorRedux(['SEND_OTP'])
      this.props.resetLoadingRedux(['SEND_OTP'])
    }

    // registration props handling
    if (nextProps.registerAgentError && nextProps.registerAgentLoading === false) {
      NotificationManager.error(nextProps.registerAgentStatus)
      this.props.resetErrorRedux(['REGISTRATION'])
      this.props.resetLoadingRedux(['REGISTRATION'])
    }
    if (nextProps.registerAgentError === false && nextProps.registerAgentLoading === false) {
      // dispatchGlobal(updateGlobalState({
      //   globalState: {
      //     isLoggedIn: true
      //   },
      //   getAgentDetailData: nextProps.registerAgentStatus
      // }))
      // // cookies.set('agent_id', nextProps.registerAgentStatus.id, { path: '/' })
      // // cookies.set('agent_code', nextProps.registerAgentStatus.agent_code, { path: '/' })
      // if (this.props.location.state.isRegistration || this.registrationData?.isRegistration) {
      //   cookies.set('isRegistrationSuccess', 'true', {
      //     path: '/',
      //     maxAge: 60 * 60 * 24 * 365 // store for 1 month
      //   })
      // }
      // NotificationManager.success('Pendaftaran berhasil')
      // this.setState({ seconds: 120, error: false, errorMessage: '' })
      this.props.resetErrorRedux(['REGISTRATION'])
      this.props.resetLoadingRedux(['REGISTRATION'])
      this.props.history.push('/registration/pin')
    }

    // login props handling
    if (nextProps.loginAgentError && nextProps.loginAgentLoading === false) {
      NotificationManager.error(nextProps.loginAgentStatus)
      this.props.resetErrorRedux(['LOGIN'])
      this.props.resetLoadingRedux(['LOGIN'])
    }
    if (nextProps.loginAgentError === false && nextProps.loginAgentLoading === false) {
      // dispatchGlobal(updateGlobalState({
      //   globalState: {
      //     isLoggedIn: true
      //   },
      //   getAgentDetailData: nextProps.loginAgentStatus
      // }))
      // // cookies.set('agent_id', nextProps.loginAgentStatus.id, {
      // //   path: '/',
      // //   maxAge: 60 * 60 * 24 * 365 // store for 1 month
      // // })
      // // cookies.set('agent_code', nextProps.loginAgentStatus.agent_code, {
      // //   path: '/',
      // //   maxAge: 60 * 60 * 24 * 365 // store for 1 month
      // // })
      // this.setState({ seconds: 120, error: false, errorMessage: '' })
      // const { from } = this.props.location.state
      // let path = '/dashboard'
      // if (from && !['/'].includes(from)) {
      //   // if pathname defined on state then move the user to that path
      //   path = from
      // }
      // this.props.history.push(path)
      // this.props.resetErrorRedux(['LOGIN'])
      // this.props.resetLoadingRedux(['LOGIN'])
    }
    if (nextProps.verifyOtpError && nextProps.verifyOtpLoading === false) {
      NotificationManager.error(nextProps.verifyOtpStatus.error_msg)
      this.props.resetErrorRedux(['VERIFY_OTP'])
      this.props.resetLoadingRedux(['VERIFY_OTP'])
    }
    if (nextProps.verifyOtpError === false && nextProps.verifyOtpLoading === false) {
      this.props.history.push('/registration/pin')
      this.props.resetErrorRedux(['VERIFY_OTP'])
      this.props.resetLoadingRedux(['VERIFY_OTP'])
    }
  }

  validateIsLoggedInAgent = () => {
    if (this.props.isLoggedIn) {
      this.props.history.replace({
        pathname: '/dashboard'
      })
    }
  }

  componentWillUnmount () {
    // remove the interval after login
    clearInterval(this.timer)
  }

  startCountDown = () => {
    const timeLeftVar = this.secondsToTime(this.state.seconds)
    this.setState({ time: timeLeftVar })
    this.startTimer()
  }

  startTimer = () => {
    if (this.timer === 0 && this.state.seconds > 0) {
      this.timer = setInterval(this.countDown, 1000)
    }
  }

  countDown = () => {
    const seconds = this.state.seconds - 1
    this.setState({
      time: this.secondsToTime(seconds),
      seconds: seconds
    })

    if (seconds === 0) {
      clearInterval(this.timer)
    }
  }

  secondsToTime = (secs) => {
    const hours = Math.floor(secs / (60 * 60))

    const divisorForMinutes = secs % (60 * 60)
    const minutes = Math.floor(divisorForMinutes / 60)

    const divisorForSeconds = divisorForMinutes % 60
    const seconds = Math.ceil(divisorForSeconds)

    const obj = {
      h: hours,
      m: minutes,
      s: seconds
    }
    return obj
  }

  handleResendOtp = (isWhatsapp, isEmail) => {
    const {
      email,
      name,
      ktp_no: ktpNo,
      npwp_no: npwpNo,
      phone_no: phoneNo,
      referral_code: referralCode,
      temp_agent_id: tempAgentId
    } = this.registrationData
    if (isWhatsapp) {
      this.registrationData.medium = 'whatsapp'
    } else if (isEmail) {
      this.registrationData.medium = 'email'
    } else {
      this.registrationData.medium = 'sms'
    }
    if (tempAgentId) {
      const body = {
        email,
        name,
        ktp_no: ktpNo,
        npwp_no: npwpNo,
        referral_code: referralCode,
        phone_no: phoneNo
      }
      if (this.registrationData.medium) {
        body.medium = 'whatsapp'
      }
      this.props.validateAgent(body)
    } else {
      const body = { phone_no: phoneNo }
      if (this.registrationData.medium) {
        body.channel = this.registrationData.medium
      }
      this.props.sendOtp(body)
    }
  }

  handleSubmit = (value) => {
    const { sendOtpStatus, location } = this.props
    // if (this.props.location.state.temp_agent_id || this.registrationData?.temp_agent_id) {
    //   this.props.registerAgent({
    //     operation_id: this.operationId || this.props.validateAgentStatus.operation_id,
    //     temp_agent_id: this.props.validateAgentStatus.temp_agent_id || this.props.location.state.temp_agent_id || this.registrationData?.temp_agent_id,
    //     otp: value
    //   })
    // } else {
    //   this.props.loginAgent({
    //     phone_no: this.props.location.state.phone_no,
    //     operation_id: sendOtpStatus.operation_id || this.operationId,
    //     otp: value
    //   })
    // }
    setToLocalStorage(REGISTRATION_DATA, {
      ...this.registrationData,
      otp: value
    })
    if (location.pathname === '/registration/verify') {
      this.props.registerAgent({
        operation_id: this.operationId || this.props.validateAgentStatus.operation_id,
        temp_agent_id: this.props.validateAgentStatus.temp_agent_id || this.props.location.state.temp_agent_id || this.registrationData?.temp_agent_id,
        otp: value
      })
    } else {
      this.props.verifyOtp({
        operation_id: this.operationId || sendOtpStatus.operation_id || this.props.validateAgentStatus.operation_id,
        otp: value
      })
    }
  }

  render () {
    const {
      location, sendOtpLoading, sendOtpError, registerAgentLoading,
      loginAgentLoading, loginAgentError, history
    } = this.props
    const { time, seconds } = this.state

    return (
      <Container
        title={location.pathname === '/login/verify' ? 'masuk' : 'daftar'}
        loader={registerAgentLoading || sendOtpLoading || loginAgentLoading}
      >
        <OtpInputWrapper
          location={location.pathname === '/login/verify'}
          isVn={this.isVNAgent}
        >
          <CustomText size={12} weight={500} textAlign='center' top='36%' bottom='8%'>
            {`Masukkan kode OTP yang terkirim ke nomor ${this.registrationData.phone_no}`}
            {/* {!!seconds && ` melalui ${this.registrationData.medium ? 'WhatsApp' : 'SMS'}`} */}
          </CustomText>
          <OtpInput
            onSubmit={this.handleSubmit}
            disabled={seconds === 0}
            error={sendOtpError || loginAgentError}
          />
          {
            seconds !== 0 ? (
              <div className='margin-top-30'>
                <CustomText textAlign='center' size={12}>
                  {'Kode OTP berakhir dalam '}
                  <b>0{time.m} : {time.s < 10 ? '0' + time.s : time.s}</b>
                </CustomText>
              </div>
            )
              : (
                <CustomText textAlign='center' size='14px' top='1rem'>
                  Tidak menerima kode OTP?
                </CustomText>
              )
          }
          {
            seconds === 0 &&
              <div className='button'>
                <Button
                  className='resend-otp'
                  onClick={() => this.handleResendOtp()}
                  id='resend-otp'
                  color={AgentColorPallette.blackGrey}
                >
                  Kirim ulang
                </Button>
                {
                  !this.isVNAgent && (
                    <Button
                      className='resent-otp-whatsapp'
                      id='resend-otp-whatsapp'
                      backgroundColor='transparent'
                      color={AgentColorPallette.primary}
                      onClick={() => this.handleResendOtp(true, false)}
                    >
                      Kirim kode OTP via Whatsapp
                    </Button>
                  )
                }
                {/* {
                  !this.isVNAgent && (
                    <Button
                      className='resent-otp-email'
                      id='resend-otp-email'
                      backgroundColor='transparent'
                      color={AgentColorPallette.primary}
                      onClick={() => this.handleResendOtp(false, true)}
                    >
                      Kirim kode OTP via Email
                    </Button>
                  )
                } */}
              </div>
          }
          <PublicFooter
            page={location.pathname === '/login/verify' ? 'otp-login' : 'otp-register'}
            history={history}
            bottom='15%'
            fullBorder
          />
          <OjkFooter />
          <NotificationContainer />
        </OtpInputWrapper>
      </Container>
    )
  }
}

OtpVerify.contextType = GlobalContext

export default connect((state) => ({
  validateAgentStatus: state.Auth.validateAgentStatus,
  validateAgentMessage: state.Auth.validateAgentMessage,

  sendOtpLoading: state.Loading.SEND_OTP,
  sendOtpError: state.Error.SEND_OTP,
  sendOtpStatus: state.Auth.sendOtpStatus,

  loginAgentLoading: state.Loading.LOGIN,
  loginAgentError: state.Error.LOGIN,
  loginAgentStatus: state.Auth.loginAgentStatus,

  registerAgentLoading: state.Loading.REGISTRATION,
  registerAgentError: state.Error.REGISTRATION,
  registerAgentStatus: state.Auth.registerAgentStatus,

  verifyOtpLoading: state.Loading.VERIFY_OTP,
  verifyOtpError: state.Error.VERIFY_OTP,
  verifyOtpStatus: state.Auth.verifyOtpStatus
}), {
  resetErrorRedux,
  resetLoadingRedux,
  sendOtp,
  loginAgent,
  registerAgent,
  resetAuthStore,
  validateAgent,
  verifyOtp
})(OtpVerify)
